"""D1b decision report and additional provenance verification from saved data only."""
from pathlib import Path
import json,math,statistics,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.prepare_d1b import POINTS,sha,read,save
D=ROOT/'results/d1b'
def main():
    a=read(D/'local_audit.json');assert read(D/'independent_audit.json')['passed'];b=read(D/'build.json');index=read(D/'build_objects/index.json');old=read(ROOT/'results/d1/build.json')['reused_original_objects_sha256'];assert b['original_spmm_objects_unchanged_sha256']==old
    for name,h in old.items():assert index[name]['sha256']==h and sha(ROOT/index[name]['saved'])==h
    costs=[];telemetry={}
    for m,n in POINTS:
        row=[]
        for i,label in [(6,'Old-HV'),(7,'New-HV-A')]:
            hosts=[];events=[];fractions=[]
            for rep in range(3):
                x=read(D/'profile'/m/f'N{n}'/f'run{rep}.json');hosts.append(statistics.median(v[1]+v[3] for v in x['host_api_us'][i]));events.append(statistics.median(v[0]+v[1] for v in x['events'][i]));fractions.append(statistics.median((v[1]+v[3])/w for v,w in zip(x['host_api_us'][i],x['records'][i]['samples_us'])))
            row.append({'label':label,'clear_host_process_medians_us':hosts,'clear_event_process_medians_us':events,'clear_host_wall_process_median_fractions':fractions,'clear_host_us':statistics.median(hosts),'clear_event_us':statistics.median(events),'clear_host_wall_fraction':statistics.median(fractions)})
        costs.append({'matrix':m,'n':n,'rows':row})
    save(D/'report_verification.json',{'passed':True,'original_spmm_objects_match_D1':True,'original_object_count':len(old),'source_analysis_sha256':sha(D/'local_audit.json'),'cost_source':'profile raw: median per-call sum, then median across3 processes','clear_costs':costs,'device_executed':False})
    lines=['# D1b：公共清零后端验证结果','','**验证通过。当前实现中，原清零路径显著影响了整体框架比较；将它统一替换为设备AIV清零后，H-V五个代表点完整调用加速1.69–10.77倍，ca与thermal也由相对V0的负例转为正向。建议冻结这一公共后端，再独立确认4/2与8/4。**','','这里只验证公共后端的工程改动，不能作为成组/分流新颖性或强库竞争力的证据。实例已在数据本地回收、独立核验后关闭；D2没有启动。','','## 唯一改了什么','','旧路径每次调用先全量清零out，存在G组时再全量清零packed，然后调用原计算核与恢复核；新路径保留完全相同的清零范围、次数与顺序，仅将两次aclrtMemsetAsync分别替换成AIV零填充kernel。没有删除或融合清零，没有跳过输出，没有改组成员、行排序、路由、4/2或长行策略。','','新zero kernel使用8192 float的UB块、按AIV核轮转写不相交区域，正式48 AIV，所有实际缓冲长度均为16 float的倍数。原SpMM static library和dispatch对象逐字节复用并与D1保存值独立交叉核对，没有重新编译原计算核。四种完整布局V0/V2/V2-Z/HV对称应用新后端，所有11种输入数组逐hash相同。','','## 正式同进程结果','','每点10个独立进程，各10预热/30采样。旧/新四布局共8记录，加新HV同实现第二记录，9记录随机交错；正式主计时无设备事件。下表比值均按每进程30个迭代配对比中位数，再对10进程做几何平均，不以两个会话绝对延迟拼接。','','| 点 | 旧/新V0 | 旧/新V2 | 旧/新V2-Z | 旧/新HV-A（条件区间） | 旧/新HV-B |','|---|---:|---:|---:|---:|---:|']
    for r in a['rows']:
        c=r['contrasts'];hv=c['Old-HV/New-HV-A'];ci=hv['bootstrap95_conditional'];lines.append(f"| {r['matrix']}/N{r['n']} | {c['Old-V0/New-V0']['geomean']:.4f} | {c['Old-V2/New-V2']['geomean']:.4f} | {c['Old-V2-Z/New-V2-Z']['geomean']:.4f} | {hv['geomean']:.4f} [{ci[0]:.4f},{ci[1]:.4f}] | {c['Old-HV/New-HV-B']['geomean']:.4f} |")
    lines+=['','H-V五点均10/10进程更快、条件区间下界>1、均值超过同层空对照保护值，HV-B也确认方向。其余布局多数改善；ns的V0仅约5.2%，虽然10/10同向且区间>1，但未超过本点6.4%的保守描述性保护值，应保留“小幅改善未过保护”的表述。','','区间为10进程log配对比的20000次bootstrap，探索性、条件性；不将30次迭代当独立设备样本。这是五个有目的挑选的代表点，不是全矩阵集总体结论。','','## 公共后端修正后，框架比较改变了什么','','| 点 | 新V0/新HV-A | 新V2/新HV-A | 新V2-Z/新HV-A | 新V2/新V2-Z | 解释 |','|---|---:|---:|---:|---:|---|']
    texts=['HV与V2的小差异未分辨；主要保留重排/块计算优势','HV相对V0与V2均有可分辨收益','HV开始胜过V0；对V2的小幅增益仍受噪声/分配敏感性限制','去零仍有收益，HV对去零后的V2仍有剩余收益','HV开始胜过V0；与V2的小差异未稳健分辨']
    for r,text in zip(a['rows'],texts):
        c=r['contrasts'];lines.append(f"| {r['matrix']}/N{r['n']} | "+' | '.join(f"{c[k]['geomean']:.4f}" for k in ['New-V0/New-HV-A','New-V2/New-HV-A','New-V2-Z/New-HV-A','New-V2/New-V2-Z'])+' | '+text+' |')
    lines+=['','ca/N256新V0/新HV-A=1.337186，条件区间[1.298164,1.375163]；thermal/N64=1.350674，[1.316992,1.385656]，均10/10同向并通过保护规则。此前“这两个点混合架构输V0”包含原清零后端的显著影响，不能直接归因于分组/分流无效。','','相对V2的结论要更克制：email约1.467×、web约1.824×通过保护；ca约1.066×虽条件区间>1，但未超过本点1.078的空对照保护值。ca的V2-Z/HV约1.088×刚过保护，但本点V2-Z/V2布局恒等，而两份分配仍有差异，不能择取较高者宣布稳健结构收益。ns/thermal与V2的小幅差异同样不作因果结论。','','web新V2/新V2-Z=1.223520（区间[1.189195,1.252868]，10/10）；新V2-Z/新HV-A=1.489552（[1.449005,1.533551]，10/10）。去整零窗解释一部分收益，但HV剩余变化仍包含非空组组织、路由、块任务及恢复量，不能等同单独分流规则贡献。','','同实现新HV空对照保护值约1.064–1.123；调用变短后，小幅差异更容易受相对噪声及不同分配影响。不得用增加迭代数冒充更多独立进程，或改用最高一次加速比。','','## 分项是否支持清零路径归因','','另15个独立进程同时保存事件与主机API边界计时；各10预热/30采样，4050诊断样本。表中先对每次调用两个清零阶段求和，再取进程中位数及三进程中位数；因此未把不同分项中位数粗暴相加作精确归因。单位μs。','','| 点 | 旧清零主机调用 | 新清零主机调用 | 旧清零事件区间 | 新清零事件区间 | 旧/新清零主机调用占墙钟 |','|---|---:|---:|---:|---:|---:|']
    for r in costs:
        o,n=r['rows'];lines.append(f"| {r['matrix']}/N{r['n']} | {o['clear_host_us']:.2f} | {n['clear_host_us']:.2f} | {o['clear_event_us']:.2f} | {n['clear_event_us']:.2f} | {o['clear_host_wall_fraction']:.1%} / {n['clear_host_wall_fraction']:.1%} |")
    lines+=['','新HV清零提交合计降至约十几到二十几μs，主机调用占比降至约0.6%–4.9%；清零对应流上事件区间也显著缩短，而主核/恢复未出现同量级倍数下降。这与“原清零路径是当前后端的重要成本来源”一致。','','事件区间含主机提交造成的流空隙；API时长也可能含runtime内部工作或等待，final sync含等待。没有将它们称为纯设备执行、纯CPU算术或纯HBM带宽，也没有通过简单相减分离CPU/设备。切换后缓存/提交节奏可能影响主核区间，不要求全部时间差恰好由两项清零相减解释。诊断里的旧键memset_submission在new标签下表示zero-kernel launch提交，字段名仅为兼容沿用。','','## 正确性、可复算与风险','','- 清零独立测试40项：1/48 AIV、0长度、16/32、8192邻近尾块、多块及约20MB，有限非零/NaN两种毒值；逐bit确认清零为+0，两侧16-float guard保持原值。','- 4个冻结小矩阵×1/24 AIC预算×D0control/新formal/新profile=24设备进程、312记录检查；覆盖全零、N33、非满窗、非连续行映射、空分支、部分负责行。','- 每记录B与-B初始检查及末轮检查，额外检查全部padding和partial未负责行仍为零；最大绝对误差5.34058e-5。未宣称每个计时迭代都拷回验证。','- 正式50进程13500样本、诊断15进程4050样本、23400含预热追踪。全部慢点保留。独立复算500进程配对比、2025成本分项中位数、968输入数组及220元数据/flag。','- 只有新增zero内核编译；原SpMM对象哈希与D1保存值一致。源码、精确二进制、编译参数/日志、原库和新zero库都保存。','- 当前V0是既有逐非零搬运/屏障实现，仍属较弱控制基线；胜过它不能推断胜过成熟AIV/稀疏库、Neutron或具有完整优化的论文实现。','- 计时是输入常驻的同步完整调用，包含清零/计算/恢复/同步，未加入CPU预处理、首次H2D或持续B上传。未证明端到端摊销收益。','','## 冻结决定与下一步','','**对本项目接下来的受控实验，冻结D1b原生AIV清零为公共后端，同时保留旧后端程序和全部旧结果。** 这一决定基于所有正确性/边界检查通过和五个代表点HV完整调用有一致改善；不将它解释为全数据集优化保证。D2/D3所有方法必须对称采用相同新后端，不再混用旧runtime清零结果。','','下次明确启动D2后，先在原三个开发矩阵/N64独立比较4/2与8/4；保持新的公共清零、完整输出、组/阈值以外实现一致，事先冻结进程级空对照与选择规则。历史8/4约10%–12%信号来自旧后端，不能直接成为新后端结论。本轮仍为4/2，未执行D2/D3或删除冗余清零。','','当前结果支持继续研究框架迁移；联合成组/分流是否有独立价值仍需L/F/J及强库基线。清零工程修正本身不能承担论文新颖性。','','## 数据与当前结束点','','原始封存artifacts/backups/d1b-final.txt和d1b-final-check.txt，8714055字节/723条目，SHA256 `5d617e6e55654ab8f76497b481ff8b7f37e1924a2ddaf8d0f0a7d964a88bd1ba`。逐条目与本地独立核验通过。正式/分项原始在measurements/与profile/，完整统计及全部进程比在分析.md，图在figures/。','','运行设备910B2/64GB，容器346b7ff15214、物理NPU7；D1是NPU1，D0是NPU5，未拼接绝对延迟。唯一浏览器读状态超时重绑已有管理页恢复，无重复设备任务；编译仅有保存的host属性/CMake变量警告，无编译/设备/数值失败。','','实例已按要求在数据保存核验后关闭；关机证明shutdown.json/.png。续跑说明.md是下一阶段的唯一滚动入口。旧阶段数据全部保留。']
    (D/'结果解读.md').write_text('\n'.join(lines)+'\n');print({'passed':True,'original_objects_cross_checked':len(old),'report':'results/d1b/结果解读.md'})
if __name__=='__main__':main()
